function aiGoldRarity(id:number){if(id<10)return'ノーマル';if(EXCHANGE_R.includes(id))return'レア';if(EXCHANGE_SR.includes(id))return'激レア';if(EXCHANGE_SSR.includes(id)||LIMITED_SSR.includes(id)||MACHINE_SSR.includes(id)||SACRED_SSR.includes(id))return'超激レア';if([LIMITED_LR,MACHINE_LR,SACRED_LR].includes(id))return'伝説レア';const r=AI_RARITY_BY_ID[id]||'基本';return r==='R'?'レア':r==='SR'?'激レア':r==='SSR'?'超激レア':r==='LR'?'伝説レア':'ノーマル'}
