function evolveChapterRewardCharacters(ai:any,tick:number){const state=obj(ai.activity),powers=obj(state.aiColorPowers),items=obj(ai.inventory_items),maxLevels=arr<any>(state.aiCharMaxLevel),evolved=obj(state.aiChapterRewardEvolved);const specs:any={20:{name:'突撃ハーランド木下',colors:15,ancient:0,rarity:'激レア'},21:{name:'異常木下',colors:10,ancient:5,rarity:'超激レア'},22:{name:'吉田',colors:100,ancient:30,rarity:'激レア'},64:{name:'富豪木下',colors:50,ancient:15,rarity:'伝説レア'}};for(const id of [20,21,22,64]){const s=specs[id];if(!arr<number>(ai.owned_characters).includes(id)||evolved[String(id)]===true||(ai.char_levels[id]||1)<30||clamp(Math.floor(num(maxLevels[id],20)),20,30)<30)continue;if(!['赤','青','黄','緑','紫'].every(color=>num(powers[color])>=s.colors)||num(items.ancient_power)<s.ancient)continue;for(const color of ['赤','青','黄','緑','紫'])powers[color]=Math.max(0,num(powers[color])-s.colors);items.ancient_power=Math.max(0,num(items.ancient_power)-s.ancient);evolved[String(id)]=true;const forms=arr<any>(state.aiCharForm);forms[id]=2;ai.inventory_items=items;ai.activity={...state,aiColorPowers:powers,aiChapterRewardEvolved:evolved,aiCharForm:forms};log(ai,'✨ '+s.name+'が第二形態へ進化（色パワー各'+s.colors+'・古代のパワー'+s.ancient+'を消費）');return true}return false}
