  const range=Math.min(.10,Math.max(0,num(c.r))/220*.10);
  const speed=Math.min(.06,Math.max(0,num(c.s))/2*.06);
  const interval=Math.min(.05,Math.max(0,1.2-num(c.i,1))/1.2*.05);
