async function run(batchStart=1,batchEnd=BATCH_SIZE){const {error:resetError}=await db.rpc('process_rank_reset');if(resetError)throw new Error('rank reset failed: '+resetError.message);const {data,error}=await db.from('ai_accounts').select('*').gte('account_id',batchStart).lte('account_id',batchEnd).order('account_id',{ascending:true}).limit(BATCH_SIZE);if(error)throw new Error(error.message);const {data:worldEventRows}=await db.from('world_event_stages').select('id,title,stage_config,active,starts_at,expires_at,lottery_ticket_reward').eq('active',true).limit(100);const eventNow=Date.now();const activeWorldEvents=arr<any>(worldEventRows).filter(s=>Date.parse(String(s.starts_at||''))<=eventNow&&Date.parse(String(s.expires_at||''))>eventNow);const {data:state}=await db.from('rank_season_state').select('penalty_character_ids,cycle').order('cycle',{ascending:false}).limit(1).maybeSingle();const cycle=Math.floor(num(state?.cycle,0));const {data:metaRows}=await db.from('rank_season_character_stats').select('character_id,wins,losses,used').eq('cycle',cycle);const metaStats=buildMeta(metaRows||[],arr<number>(state?.penalty_character_ids));const ais=data||[];const tick=Math.floor(Date.now()/120000);await createAIAlliances(ais,tick);await createAIJoinRequests(ais,tick);await processAIJoinRequests(tick);await processAllianceInvites(ais);await postAllianceAIMessages(ais,tick);const counts:any={stage:0,rank:0,event:0,worldEvent:0,train:0,gacha:0,battle:0,growth:0,ancientGrowth:0,rarityGold:0,chest:0,itemExchange:0};let rankMatches=0;const rankCandidates:any[]=[];for(const ai of ais){norm(ai);const missionBefore={stage:Math.max(0,num(ai.stage_clears)),levels:countLevels(ai),owned:arr<number>(ai.owned_characters).slice(),evolutions:countEvolutions(ai),events:Object.keys(obj(ai.event_clears)).filter(k=>obj(ai.event_clears)[k]===true).length,worldEvents:Object.keys(obj(obj(ai.activity).aiWorldEventClaims)).filter(k=>obj(obj(ai.activity).aiWorldEventClaims)[k]===true).length};let gachaPurchases=0;ai.activity={...(obj(ai.activity)),castle_hp_bonus:Math.max(0,ai.chapter_clears[3]*150)};chooseFormation(ai,tick+ai.account_id,metaStats);dailyLogin(ai);const invBeforeAction=obj(ai.inventory_items),latestMissingBeforeAction=[65,66,67,68,69,70].some(id=>!arr<number>(ai.owned_characters).includes(id)),a=(num(invBeforeAction.latest_character_exchange_chest)>0&&latestMissingBeforeAction)?'chest':choose(ai,tick+ai.account_id,activeWorldEvents);counts[a]++;if(a==='rank'){rankCandidates.push(ai)}else if(a==='stage'){const space=ai.chapter_clears[2]>=48&&ai.chapter_clears[4]<48&&((ai.account_id+tick)%3===0||ai.chapter_clears[3]>=48);const future=!space&&ai.chapter_clears[3]<48&&((ai.account_id+tick)%2===0||ai.chapter_clears[0]>=48);stage(ai,tick,future,space)}else if(a==='event')event(ai,tick);else if(a==='worldEvent')worldEventStage(ai,tick,activeWorldEvents);else if(a==='growth')farmGrowth(ai,tick);else if(a==='ancientGrowth')farmAncientGrowth(ai,tick);else if(a==='rarityGold')farmRarityGold(ai,tick);else if(a==='chest')openAIChest(ai,tick);else if(a==='itemExchange')exchangeItems(ai,tick);else if(a==='train'){if(!level(ai,tick))log(ai,`📈 ${prof(ai).p}：XPを貯蓄`)}else if(a==='gacha'){if(gacha(ai))gachaPurchases++;else log(ai,`🪙 ${prof(ai).p}：コイン貯蓄`)}else{ai.matches++;if(rnd(`${ai.account_id}:battle:${tick}`)>.5){log(ai,`⚔️ ${prof(ai).p}：AI実戦勝利（RP変動なし）`)}else{log(ai,`⚔️ ${prof(ai).p}：AI実戦敗北（RP変動なし）`)}}if(rnd(`${ai.account_id}:post:${tick}`)>.58)level(ai,tick);runAIProgression(ai,tick+ai.account_id);if(rnd(`${ai.account_id}:skilltree:${tick}`)<.18)trainSkillTree(ai,tick);if(rnd(`${ai.account_id}:gold-convert:${tick}`)<.12)convertAIExchangeGold(ai,tick);const shopChance=ai.coins>=50000?0.98:ai.coins>=10000?0.90:ai.coins>=6000?0.82:ai.coins>=2000?0.68:0.45;if(rnd(`${ai.account_id}:shop:${tick}`)<shopChance&&gacha(ai))gachaPurchases++;if(rnd(`${ai.account_id}:shop2:${tick}`)<0.32&&ai.coins>=10000&&gacha(ai))gachaPurchases++;const newOwned=arr<number>(ai.owned_characters).filter(id=>!missionBefore.owned.includes(id)&&![RAGE,WAVE,YABASUGI,...REWARDS].includes(id)).length;const newEvents=Object.keys(obj(ai.event_clears)).filter(k=>obj(ai.event_clears)[k]===true).length-missionBefore.events;const newWorldEvents=Object.keys(obj(obj(ai.activity).aiWorldEventClaims)).filter(k=>obj(obj(ai.activity).aiWorldEventClaims)[k]===true).length-missionBefore.worldEvents;const achievementDeltas={stageWins:Math.max(0,num(ai.stage_clears)-missionBefore.stage),levelUps:Math.max(0,countLevels(ai)-missionBefore.levels),gachaBuys:gachaPurchases,evolutions:Math.max(0,countEvolutions(ai)-missionBefore.evolutions),eventWins:Math.max(0,newEvents+newWorldEvents)};processAIMissions(ai,achievementDeltas);processAIAchievements(ai,achievementDeltas);ai.coins+=10;norm(ai)}await issueAILotteryTickets(ais);rankCandidates.sort((a,b)=>num(a.rp)-num(b.rp)||num(a.account_id)-num(b.account_id));const rankUsage={winner:[] as number[],loser:[] as number[],winnerDeployments:[] as number[],loserDeployments:[] as number[]};for(let i=0;i+1<rankCandidates.length;i+=2){for(let matchNo=0;matchNo<10;matchNo++){const rr=rankPair(rankCandidates[i],rankCandidates[i+1],tick+matchNo);rankUsage.winner.push(...rr.winnerIds);rankUsage.loser.push(...rr.loserIds);rankUsage.winnerDeployments.push(...rr.winnerDeployments);rankUsage.loserDeployments.push(...rr.loserDeployments);rankMatches++;}}const now=new Date().toISOString();for(let offset=0;offset<ais.length;offset+=50){const batch=ais.slice(offset,offset+50);for(const ai of batch)ai.updated_at=now;const {error:up}=await db.from('ai_accounts').upsert(batch,{onConflict:'account_id'});if(up)throw new Error('AI account save failed ('+batch[0]?.account_id+'-'+batch[batch.length-1]?.account_id+'): '+up.message);}const {data:savedRows,error:verifyError}=await db.from('ai_accounts').select('account_id,updated_at').gte('account_id',batchStart).lte('account_id',batchEnd).order('account_id',{ascending:true});if(verifyError)throw new Error('AI account save verification failed: '+verifyError.message);if(!savedRows||savedRows.length!==ais.length)throw new Error('AI account save verification count mismatch: expected '+ais.length+', got '+(savedRows?.length||0));const stale=savedRows.filter((row:any)=>!row.updated_at||Date.parse(String(row.updated_at))<Date.parse(now));if(stale.length)throw new Error('AI account save verification found stale rows: '+stale.slice(0,10).map((row:any)=>row.account_id).join(','));if(rankMatches){const {error:metaUp}=await db.rpc('record_rank_character_match',{p_cycle:cycle,p_winner_ids:rankUsage.winnerDeployments,p_loser_ids:rankUsage.loserDeployments});if(metaUp)throw new Error('rank character stats update failed after account save: '+metaUp.message);}const msg=`AI-${batchStart}〜AI-${batchEnd} / ステージ${counts.stage}・ランク候補${counts.rank}・実ランク戦${rankMatches}・イベント${counts.event}・育成${counts.train}・交換${counts.gacha}・実戦${counts.battle}・保存確認${savedRows.length}/${ais.length}`;const {error:stateError}=await db.from('ai_server_state').upsert({id:1,last_run_at:now,last_run_count:ais.length,last_run_message:msg,updated_at:now},{onConflict:'id'});if(stateError)throw new Error('AI server state save failed: '+stateError.message);return{ok:true,processed:ais.length,actions:counts,accountSaveVerified:savedRows.length,last_run_at:now}}
let db:any=null;function getDb(){if(db)return db;if(!URL)throw new Error('SUPABASE_URL missing');let key=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'';if(!key&&RAW){try{const sec:any=JSON.parse(RAW);key=String(sec.default||'')}catch{throw new Error('secret parse error')}}if(!key)throw new Error('service key missing');db=createClient(URL,key,{auth:{persistSession:false,autoRefreshToken:false}});return db}Deno.serve(async req=>{if(req.method!=='POST')return res({ok:false,error:'POST only'},405);if(!TOKEN||req.headers.get('x-ai-worker-token')!==TOKEN)return res({ok:false,error:'Unauthorized'},401);try{getDb();let body:any={};try{body=await req.json()}catch{}const start=Math.max(1,Math.min(TOTAL,Math.floor(num(body?.batchStart,1))));const end=Math.max(start,Math.min(TOTAL,Math.floor(num(body?.batchEnd,Math.min(TOTAL,start+BATCH_SIZE-1)))));return res(await run(start,end))}catch(e){console.error(e);return res({ok:false,error:e instanceof Error?e.message:String(e)},500)}})
